(()=>{document.addEventListener("DOMContentLoaded",()=>{let r=document.querySelectorAll(".ws-brand-list");r.length&&r.forEach(o=>{let e=o.querySelectorAll(".ws-brand-list__item");e.forEach(n=>{n.addEventListener("keydown",t=>{if(t.key!=="ArrowRight"&&t.key!=="ArrowLeft")return;t.preventDefault();let d=Array.from(e).indexOf(n),s=t.key==="ArrowRight"?1:-1,c=(d+s+e.length)%e.length;e[c].focus()})})})});})();
